import { PageBlock } from 'hanoryx-components/page';
<PageBlock block={{
  "type": "signature",
  "kind": "accordionList",
  "anchor": "principles",
  "railLabel": "How North builds",
  "scene": "privacy-quiet-grid",
  "minHeight": 560,
  "eyebrow": "Engineering principles",
  "title": "How North builds.",
  "intro": "Six habits that shape the work. Open any of them.",
  "defaultOpen": "e-01",
  "marker": "north.principles-accordion",
  "items": [
    {
      "id": "e-01",
      "title": "Foundations first",
      "meta": "ENG.01",
      "body": "Start with the data model, constraints, and service boundaries before committing to an interface."
    },
    {
      "id": "e-02",
      "title": "Systems, not screens",
      "meta": "ENG.02",
      "body": "Design interactions and reusable components for the workflow rather than isolated page states."
    },
    {
      "id": "e-03",
      "title": "Scoped by design",
      "meta": "ENG.03",
      "body": "Model roles, access, and data ownership as part of the architecture."
    },
    {
      "id": "e-04",
      "title": "Observe what matters",
      "meta": "ENG.04",
      "body": "Identify the signals needed to understand behavior and failure before a system is released."
    },
    {
      "id": "e-05",
      "title": "Reversible decisions",
      "meta": "ENG.05",
      "body": "Prefer changes with a recovery path and isolate those that cannot be undone."
    },
    {
      "id": "e-06",
      "title": "Quiet by default",
      "meta": "ENG.06",
      "body": "Surface useful state without turning every screen into an alarm."
    }
  ]
}} />

