      "choices": [
        {
          "label": "A few words or a number",
          "picks": [
            {
              "id": "textField",
              "why": "One line with a label, a hint and an error that is announced. Add a prefix or suffix for a unit."
            },
            {
              "id": "numberField",
              "why": "If it is a quantity with a range: arrows step it, typing is free, and it is clamped when you leave."
            }
          ]
        },
        {
          "label": "One choice from a few",
          "picks": [
            {
              "id": "radioGroup",
              "why": "Native radios: the arrows choose, and a screen reader says “2 of 4”."
            },
            {
              "id": "segmented",
              "why": "When the choices are short and few and the control should read as one piece."
            }
          ]
        },
        {
          "label": "One choice from many",
          "picks": [
            {
              "id": "selectField",
              "why": "Native, so a phone gives its own picker. The first thing to try."
            },
            {
              "id": "combobox",
              "why": "When the list is long enough that people will want to type to find their answer."
            }
          ]
        },
        {
          "label": "Several things",
          "picks": [
            {
              "id": "checkbox",
              "why": "Each option is its own box; a parent box can show the mixed state."
            },
            {
              "id": "tagInput",
              "why": "When people supply their own words rather than choosing from a list."
            }
          ]
        },
        {
          "label": "A file",
          "picks": [
            {
              "id": "fileDrop",
              "why": "Drag and drop, with a real file button underneath for everyone else."
            }
          ]
        }
      ]
    },
    {
      "id": "move",
      "label": "Help people move",
      "ask": "How?",
      "choices": [
        {
          "label": "Show where they are",
          "picks": [
            {
              "id": "breadcrumbs",
              "why": "A trail back up the site, with the current page marked."
            },
