            {
              "id": "tabs",
              "why": "When each choice shows a different panel of content."
            },
            {
              "id": "segmented",
              "why": "When each choice only changes a setting or a nearby demonstration."
            }
          ]
        },
        {
          "label": "Offer a set of actions",
          "picks": [
            {
              "id": "dropdownMenu",
              "why": "A button that opens a menu of actions, with typeahead and Escape."
