            },
            {
              "id": "skeleton",
              "why": "When you know the shape of what is coming and want nothing to jump."
            },
            {
              "id": "progressBar",
              "why": "When you know how far along it is."
            }
          ]
        },
        {
          "label": "There is nothing to show",
          "picks": [
            {
              "id": "emptyState",
              "why": "Say why, and say what to do next."
            }
