          ]
        },
        {
          "label": "Facts about one thing",
          "picks": [
            {
              "id": "descriptionList",
              "why": "Labels and values, paired in the markup."
            },
            {
              "id": "stat",
              "why": "For the one number that matters, with how it moved."
            }
          ]
        },
        {
          "label": "A trend",
          "picks": [
            {
              "id": "sparkline",
              "why": "Direction at a glance, with a text description of the range."
