          ]
        },
        {
          "label": "Things inside things",
          "picks": [
            {
              "id": "tree",
              "why": "One tab stop, arrow keys to walk it."
            }
          ]
        },
        {
          "label": "Code",
          "picks": [
            {
              "id": "codeBlock",
              "why": "With a copy button, optional line numbers and light colouring."
            }
          ]
        }
      ]
    },
    {
      "id": "attention",
