  "minHeight": 780,
  "title": "Where does it belong?",
  "lede": "Eight small responsibilities and four layers. Put each in the layer you would give it, then check against the reasoning. There is rarely only one possible answer; the point is to say why.",
  "layers": [
    {
      "id": "interface",
      "name": "Interface",
      "blurb": "Shows things and takes input. Presentation, and nothing that has to be true."
    },
    {
      "id": "surface",
      "name": "Service surface",
      "blurb": "The typed contracts. Who may ask for what, and what shape the question and answer take."
    },
    {
      "id": "orchestration",
      "name": "Orchestration",
      "blurb": "Moves work between states: steps, retries, hand-offs, schedules."
    },
    {
      "id": "data",
      "name": "Data core",
      "blurb": "Owns the truth. One writer per record, with rules that cannot be bypassed."
    }
  ],
  "items": [
    {
      "id": "a",
      "text": "Show a price with a currency symbol and two decimals",
      "layer": "interface",
      "why": "Presentation is the edge’s job. The data core stores an amount and a currency code, and every screen formats it for its reader."
    },
    {
      "id": "b",
      "text": "Check that this person may issue a refund",
      "layer": "surface",
      "why": "Authorisation belongs at the boundary of the service, decided there for every request, so no path can skip it."
    },
    {
      "id": "c",
      "text": "Move an order from paid to packed and tell the warehouse",
      "layer": "orchestration",
      "why": "Moving work between states, and telling other parts about it, is orchestration. State moves; it is not edited loosely."
    },
    {
      "id": "d",
      "text": "Make sure two people cannot change one record at the same moment",
      "layer": "data",
      "why": "Only the layer that owns the record can guarantee this, with a transaction or a version check that cannot be bypassed."
    },
    {
      "id": "e",
      "text": "Retry a failed email three times, then give up",
      "layer": "orchestration",
      "why": "Retries, back-off and the point of giving up are about the progress of work, not about data or screens."
    },
    {
      "id": "f",
      "text": "Reject a request that is missing a field it promised to carry",
      "layer": "surface",
      "why": "The contract states the shape of a request. Enforcing it at the surface keeps bad input from travelling any further."
    },
    {
      "id": "g",
      "text": "Remember that this order has been refunded",
      "layer": "data",
      "why": "A fact about the world is stored where truth lives, once. Everything else reads it."
