<PageBlock block={{
  "type": "closer",
  "kind": "whichOne",
  "anchor": "which",
  "scene": "trigger-action-pulse",
  "tag": "End of triggers",
  "minHeight": 640,
  "title": "Which one for this job?",
  "lede": "Three questions about the job in front of you. The answer names the trigger that fits, and why the others do not.",
  "questions": [
    {
      "id": "q1",
      "text": "What starts the work?",
      "options": [
        "The time of day",
        "Something that happened"
      ]
    },
    {
      "id": "q2",
      "text": "Who needs to react?",
      "options": [
        "One known worker",
        "Several, some not yet known"
      ]
    },
    {
      "id": "q3",
      "text": "Can one item fail without the others?",
      "options": [
        "No — one run covers the lot",
        "Yes — each item stands alone"
      ]
    }
  ],
  "outcomes": {
    "100": {
      "name": "A queue",
      "why": "Something happened, one worker handles it, and one pass is enough. A queue smooths the burst and keeps the backlog visible.",
      "watch": "The age of the oldest job, not only the count."
    },
    "101": {
      "name": "A queue with retries and a dead-letter queue",
      "why": "Something happened and each item can fail alone. Give each job a limited number of attempts, then set it aside for a person.",
      "watch": "A dead-letter queue nobody reads is just a bin."
    },
    "110": {
      "name": "Events",
      "why": "A fact has occurred and several parts need to react, some not yet known. Publish it and let them subscribe.",
      "watch": "The shape of the event is a contract. Version it."
    },
    "111": {
      "name": "Events, with a queue behind each consumer",
      "why": "A fact, many consumers, and items that can fail alone. Publish the event; give each consumer a queue with its own retries.",
      "watch": "Replays. Consumers must recognise an event they have already handled."
    },
    "000": {
      "name": "Cron",
      "why": "The clock is the reason, one worker handles it, and one run covers the lot. This is what cron is for.",
      "watch": "A cron job that silently stops. Add a heartbeat, and skip a run if the last one is still going."
    },
    "001": {
      "name": "Cron that feeds a queue",
      "why": "The time starts it, but each item can fail alone. Let cron decide what is due and put one job per item on a queue.",
      "watch": "Duplicates: a job can arrive twice. Record what is done in the same transaction as the effect."
    },
    "010": {
      "name": "Cron that publishes an event",
      "why": "The clock starts it, but several parts of the system care. Have the schedule announce a fact, such as “day closed”, and let others react.",
      "watch": "Consumers that miss the event. Watch each one’s lag."
    },
    "011": {
      "name": "A scheduled event, with a queue behind each consumer",
      "why": "Time starts it, many react, and each item can fail alone. Publish on a schedule, and give each consumer its own queue.",
      "watch": "A tangle. Name each event as a fact and give it an id."
    },
    "default": {
      "name": "A queue",
      "why": "When in doubt, a queue is the most forgiving: it smooths bursts, retries one item at a time and shows its backlog.",
      "watch": "Make the work safe to repeat."
    }
